BEGIN;
CREATE SCHEMA analytics_test;
CREATE FUNCTION analytics_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION analytics_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA analytics_test TO authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA analytics_test TO authenticated;
INSERT INTO auth.users(id,email) SELECT ('27000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'analytics-'||n||'@example.invalid' FROM generate_series(1,6)n;
INSERT INTO public.companies(id,nome,created_by) VALUES('17000000-0000-4000-8000-000000000001','Analytics fixture','27000000-0000-4000-8000-000000000001'),('17000000-0000-4000-8000-000000000002','Other analytics fixture','27000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) SELECT '17000000-0000-4000-8000-000000000001',('27000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'auditor',(ARRAY['admin_empresa','analista_transporte','supervisor','operador_logistico','motorista','cliente'])[n],'27000000-0000-4000-8000-000000000001' FROM generate_series(1,6)n;
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT set_config('analytics_test.branch1',public.maintenance_branch_command('17000000-0000-4000-8000-000000000001','save','{"nome":"Unidade Norte","ativo":true}')->>'id',true);
SELECT set_config('analytics_test.branch2',public.maintenance_branch_command('17000000-0000-4000-8000-000000000001','save','{"nome":"Unidade Sul","ativo":true}')->>'id',true);
RESET ROLE;
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual,branch_id) VALUES('37000000-0000-4000-8000-000000000001','17000000-0000-4000-8000-000000000001','ANL0001','caminhao','Fixture 1',3000,current_setting('analytics_test.branch1')::uuid),('37000000-0000-4000-8000-000000000002','17000000-0000-4000-8000-000000000001','ANL0002','caminhao','Fixture 2',5000,current_setting('analytics_test.branch2')::uuid);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,created_by) VALUES('47000000-0000-4000-8000-000000000001','17000000-0000-4000-8000-000000000001','Analytics workshop','27000000-0000-4000-8000-000000000001');
INSERT INTO public.maintenance_orders(id,company_id,vehicle_id,partner_id,created_by,tipo,km_abertura,data_abertura,previsao_entrega,descricao_problema) VALUES('57000000-0000-4000-8000-000000000001','17000000-0000-4000-8000-000000000001','37000000-0000-4000-8000-000000000001','47000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','corretiva',1000,'2026-01-10 08:00:00-03','2026-01-14 00:00:00-03','Historical repair');
INSERT INTO public.maintenance_order_items(company_id,order_id,created_by,tipo,descricao,quantidade,valor_unitario) VALUES('17000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','servico','Repair',1,1000);
INSERT INTO public.workshop_visits(company_id,vehicle_id,order_id,partner_id,created_by,registrado_por,chegada_em,saida_em,km_chegada,km_saida) VALUES
('17000000-0000-4000-8000-000000000001','37000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','47000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','2026-01-10 00:00:00-03','2026-01-13 00:00:00-03',1000,2000),
('17000000-0000-4000-8000-000000000001','37000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','47000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','2026-01-11 00:00:00-03','2026-01-12 00:00:00-03',1100,1500);
INSERT INTO public.maintenance_order_timeline(company_id,order_id,created_by,usuario_id,tipo_evento,descricao,dados,created_at) VALUES('17000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','comentario','Execution','{"status_novo":"em_execucao"}','2026-01-10 00:00:00-03'),('17000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','comentario','Completed','{"status_novo":"concluido"}','2026-01-12 00:00:00-03');
UPDATE public.maintenance_orders SET status='encerrada' WHERE id='57000000-0000-4000-8000-000000000001';
INSERT INTO public.maintenance_orders(id,company_id,vehicle_id,partner_id,created_by,tipo,km_abertura,data_abertura,previsao_entrega,descricao_problema,prioridade,status) VALUES('57000000-0000-4000-8000-000000000002','17000000-0000-4000-8000-000000000001','37000000-0000-4000-8000-000000000002','47000000-0000-4000-8000-000000000001','27000000-0000-4000-8000-000000000001','corretiva',5000,current_date-2,current_date-1,'Critical open repair','critica','aguardando_peca');
CREATE FUNCTION analytics_test.act(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER AS $$ SELECT public.maintenance_analytics_command('17000000-0000-4000-8000-000000000001',action,jsonb_build_object('start','2026-01-01','end',current_date)||payload);$$;
GRANT EXECUTE ON FUNCTION analytics_test.act(text,jsonb) TO authenticated;
SET LOCAL ROLE authenticated;
SELECT analytics_test.assert(jsonb_array_length(analytics_test.act('context')->'branches')=2,'branch context');
SELECT analytics_test.assert((analytics_test.act('dashboard')->'cards'->>'custo')::numeric=1000,'closed costs only');
SELECT analytics_test.assert((analytics_test.act('dashboard')->'cards'->>'manutencao')::integer=1,'current maintenance count');
SELECT analytics_test.assert((analytics_test.act('dashboard')->'cards'->>'disponibilidade')::numeric=50,'current availability');
SELECT analytics_test.assert((analytics_test.act('dashboard')->'cards'->>'peca')::integer=1,'waiting parts');
SELECT analytics_test.assert(jsonb_array_length(analytics_test.act('dashboard')->'critical')=1,'critical link');
SELECT analytics_test.assert((analytics_test.act('dashboard','{"start":"2026-01-11","end":"2026-01-12"}')->'downtime'->0->>'downtime_horas')::numeric=48,'clip and merge overlapping visits');
SELECT analytics_test.assert((analytics_test.act('report','{"report":"vehicles"}')->'rows'->0->>'custo_km')::numeric=1,'cost per observed KM');
SELECT analytics_test.assert(analytics_test.act('report','{"report":"vehicles"}')->'rows'->1->>'custo_km' IS NULL,'no fabricated odometer denominator');
SELECT analytics_test.assert((analytics_test.act('report','{"report":"history","size":1}')->>'count')::integer=2 AND jsonb_array_length(analytics_test.act('report','{"report":"history","size":1}')->'rows')=1,'pagination count');
SELECT analytics_test.assert((analytics_test.act('dashboard',jsonb_build_object('branch_id',current_setting('analytics_test.branch2')))->'cards'->>'custo')::numeric=0,'branch filter isolates costs');
SELECT analytics_test.denied($q$SELECT public.maintenance_analytics_command('17000000-0000-4000-8000-000000000002','context','{}')$q$);
SELECT analytics_test.denied($q$SELECT analytics_test.act('dashboard','{"start":"2026-02-01","end":"2026-01-01"}')$q$);
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000003',true);
SELECT analytics_test.assert((analytics_test.act('dashboard')->'cards'->>'custo')::numeric=1000,'supervisor sees financials by user authorization');
SELECT analytics_test.denied($q$SELECT public.maintenance_branch_command('17000000-0000-4000-8000-000000000001','save','{"nome":"Denied"}')$q$);
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000004',true);
SELECT analytics_test.assert((analytics_test.act('report','{"report":"types"}')->'rows'->0->>'custo_total')::numeric=1000,'operator sees financial report');
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000005',true);SELECT analytics_test.denied($q$SELECT analytics_test.act('dashboard')$q$);
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000006',true);SELECT analytics_test.denied($q$SELECT analytics_test.act('report')$q$);
SELECT set_config('request.jwt.claim.sub','27000000-0000-4000-8000-000000000001',true);RESET ROLE;
UPDATE public.veiculos SET branch_id=current_setting('analytics_test.branch2')::uuid WHERE id='37000000-0000-4000-8000-000000000001';
SET LOCAL ROLE authenticated;
SELECT analytics_test.assert((analytics_test.act('dashboard',jsonb_build_object('branch_id',current_setting('analytics_test.branch1')))->'cards'->>'custo')::numeric=1000,'historical branch retained after moving fleet');
SELECT analytics_test.assert(NOT has_function_privilege('anon','public.maintenance_analytics_command(uuid,text,jsonb)','EXECUTE'),'anonymous denied');
SELECT analytics_test.assert(NOT has_table_privilege('authenticated','public.maintenance_branches','INSERT'),'branch writes require checked RPC');
SELECT analytics_test.assert((SELECT count(*)>=3 FROM public.maintenance_analytics_audit WHERE company_id='17000000-0000-4000-8000-000000000001'),'branch audit exists');
RESET ROLE;ROLLBACK;
